// Totals for an invoice. Prices are in cents.
export function subtotal(lines) {
  return lines.reduce((sum, line) => sum + line.price * line.qty, 0);
}

export function applyDiscount(amount, percent) {
  // BUG: percent is treated as a fraction already
  return Math.round(amount - amount * percent);
}

export function total(lines, discountPercent = 0, taxRate = 0.1) {
  const discounted = applyDiscount(subtotal(lines), discountPercent);
  return Math.round(discounted * (1 + taxRate));
}

